ev = [("e1","call","r1"),("e2","board","r1"),("e2","board","r1"),("e3","alight","r1"),
      ("e4","call","r2"),("e5","board",None),("e6","board","r3")]
seen, uniq = set(), []
for e in ev:
    if e[0] not in seen:
        seen.add(e[0]); uniq.append(e)
rides = {}
for _, typ, ride in uniq:
    if ride: rides.setdefault(ride, set()).add(typ)
print("중복", len(ev) - len(uniq), "건")
print("ride_id 빈칸", f"{sum(e[2] is None for e in uniq) / len(uniq):.1%}")
print("탔는데 내린 기록 없음", sorted(r for r, s in rides.items() if "board" in s and "alight" not in s))
# 중복 1 건
# ride_id 빈칸 16.7%
# 탔는데 내린 기록 없음 ['r3']
